map "https://fhir.hl7.at/elga/cda2fhir/r4/StructureMap/at-cda-emed-to-fhir-bundle" = "CdaEmedToFhirBundle"

//
// Mapping ELGA-CDA eMedikation to FHIR
//

conceptmap "cda-emed-clinicaldocument-code-2-fhir-category" {
  prefix s = "http://loinc.org"

  s: "56445-0" == s: "56445-0"
  s: "57833-6" == s: "57833-6"
  s: "60593-1" == s: "60593-1"
}

/*conceptmap "elga-Einnahmezeitpunkte-fhir-timing-abbreviation" {
  prefix s = "https://termgit.elga.gv.at/CodeSystem/asp-liste",
         t = "http://terminology.hl7.org/CodeSystem/v3-GTSAbbreviation"

  s: "Morgens" == t: "AM"
  s: "Mittags" == t: "???"
  s: "Abends" == t: "BED"
  s: "Nachts" == t: "???"
}*/

uses "http://hl7.org/cda/stds/core/StructureDefinition/ClinicalDocument" alias ClinicalDocument as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Author" alias Author as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/AssignedAuthor" alias AssignedAuthor as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/AssignedEntity" alias AssignedEntity as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/AssociatedEntity" alias AssociatedEntity as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/CustodianOrganization" alias CustodianOrganization as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Section" alias Section as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/PatientRole" alias PatientRole as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/StructuredBody" alias StructuredBody as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Observation" alias CDAObservation as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Performer2" alias Performer as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Procedure" alias Procedure as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Organizer" alias Organizer as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Participant1" alias Participant as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Act" alias Act as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Supply" alias Supply as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Reference" alias CDAReference as source

uses "http://hl7.org/fhir/4.3/StructureDefinition/Bundle" alias Bundle as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/Composition" alias Composition as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/Patient" alias Patient as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/Person" alias Person as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/Practitioner" alias Practitioner as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/PractitionerRole" alias PractitionerRole as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/Organization" alias Organization as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/DiagnosticReport" alias DiagnosticReport as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/ServiceRequest" alias ServiceRequest as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/Observation" alias Observation as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/Medication" alias Medication as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/MedicationDispense" alias MedicationDispense as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/MedicationRequest" alias MedicationRequest as target

imports "http://hl7.at/fhir/HL7ATCoreProfiles/4.0.1/StructureMap/at-cda-to-fhir-types"


// _________________________ Document Level Template  _________________________

group CdaEmedToFhirBundle(source cda: ClinicalDocument, target fhir_patient: Patient, target fhir_composition: Composition, target fhir_bundle: Bundle) { // Mapping ELGA-CDA eMedikation to FHIR
  cda ->   
    // at least on Bundle level the profile is to be set
    fhir_bundle.meta as fhir_bundle_meta,
    fhir_bundle_meta.profile = 'https://fhir.hl7.at/elga/aps/r4/StructureDefinition/at-aps-bundle',
    fhir_patient.meta as fhir_patient_meta,
    fhir_patient_meta.profile = 'https://fhir.hl7.at/elga/aps/r4/StructureDefinition/at-aps-patient'
    then {
      // map the CDA header
      cda then CdaEmedHeaderToFhirComposition(cda, fhir_composition, fhir_patient, fhir_bundle) "CdaEmedHeaderToFhirComposition";
      cda then CdaEmedHeaderToFhir(cda, fhir_composition, fhir_patient, fhir_bundle) "CdaEmedHeaderToFhir"; 

      // map the CDA body
      //ClinicalDocument/component
      cda.component as cda_component then {
        // ClinicalDocument/component/structuredBody
        cda_component.structuredBody as cda_structuredBody
          then CdaEmedBodyToFhir(cda, cda_structuredBody, fhir_composition, fhir_patient, fhir_bundle);
      };
    } "CdaEmedToFhirBundle"; 
}

// _________________________ Header Level Templates _________________________

group CdaEmedHeaderToFhirComposition(source cda : ClinicalDocument, target fhir_composition : Composition, target fhir_patient: Patient, target fhir_bundle: Bundle) extends CdaHeaderToFhirComposition {
   
  cda.code as cda_code then {

  // Set Profile of Composition
  cda_code ->
    fhir_composition.meta as fhir_composition_meta,
    fhir_composition_meta.profile = 'https://fhir.hl7.at/elga/aps/r4/StructureDefinition/at-aps-composition' "CdaEmedSetAPSCompositionProfile";

   // ClinicalDocument/code -> Composition.category
   cda_code.code as code_code ->
    fhir_composition.category as fhir_composition_category,
    fhir_composition_category.coding = translate(code_code, '#cda-emed-clinicaldocument-code-2-fhir-category' , 'Coding') "CdaEmedCodeToFhirCompositionCategory";

   // ClinicalDocument/code/translation (document class) -> Composition.type
   // for CDA eMedication, translation is fixed to 52471-0 LOINC
   cda_code.translation -> fhir_composition.type "CdaEmedCodeTranslationToFhirCompositionType";
   // in case CDA does not have translation, the Composition.type will be explicitly set (currently set to 60591-5 for valid APS Bundle)
   cda_code where cda_code.translation.exists().not() ->
     fhir_composition.type = create('CodeableConcept') as type_coding,
     type_coding.coding = create('Coding') as coding_coding,
     coding_coding.system = 'http://loinc.org',
     coding_coding.code = '60591-5'
     "CdaEmedMissingCodeTranslationToFhirCompositionType";

  } "CdaEmedCodeToFhirComposition";
   
}

group CdaEmedHeaderToFhir(source cda: ClinicalDocument, target fhir_composition: Composition, target fhir_patient: Patient, target fhir_bundle: Bundle) extends CdaHeaderToFhir {
}

// _________________________ Body Level Templates ____________________________

group CdaEmedBodyToFhir(source cda: ClinicalDocument, source cda_structuredBody: StructuredBody, target fhir_composition: Composition, target fhir_patient: Patient, target fhir_bundle: Bundle) {
   
  // prefill required APS sections in order to have a valid APS instance
  cda_structuredBody ->
  // section problems
    fhir_composition.section as fhir_composition_problems_section,
    fhir_composition_problems_section.title = 'Gesundheitsprobleme und Risiken (Problems)',
    fhir_composition_problems_section.code as fhir_composition_problems_section_code,
    fhir_composition_problems_section_code.coding as fhir_composition_problems_section_code_coding,
    fhir_composition_problems_section_code_coding.system = 'http://loinc.org',
    fhir_composition_problems_section_code_coding.code = '11450-4',
    fhir_composition_problems_section.emptyReason as fhir_composition_problems_section_emptyReason,
    fhir_composition_problems_section_emptyReason.coding as fhir_composition_problems_section_emptyReason_coding,
    fhir_composition_problems_section_emptyReason_coding.system = 'http://terminology.hl7.org/CodeSystem/list-empty-reason',
    fhir_composition_problems_section_emptyReason_coding.code = 'unavailable',
    fhir_composition_problems_section.text as fhir_composition_problems_section_text,
    fhir_composition_problems_section_text.status = 'empty',
    fhir_composition_problems_section_text.div = append('Kein Text für diese Section vorhanden.'),

    // section allergies
    fhir_composition.section as fhir_composition_allergies_section,
    fhir_composition_allergies_section.title = 'Allergien und Intoleranzen (Allergies and Intolerances)',
    fhir_composition_allergies_section.code as fhir_composition_allergies_section_code,
    fhir_composition_allergies_section_code.coding as fhir_composition_allergies_section_code_coding,
    fhir_composition_allergies_section_code_coding.system = 'http://loinc.org',
    fhir_composition_allergies_section_code_coding.code = '48765-2',
    fhir_composition_allergies_section.emptyReason as fhir_composition_allergies_section_emptyReason,
    fhir_composition_allergies_section_emptyReason.coding as fhir_composition_allergies_section_emptyReason_coding,
    fhir_composition_allergies_section_emptyReason_coding.system = 'http://terminology.hl7.org/CodeSystem/list-empty-reason',
    fhir_composition_allergies_section_emptyReason_coding.code = 'unavailable',
    fhir_composition_allergies_section.text as fhir_composition_allergies_section_text,
    fhir_composition_allergies_section_text.status = 'empty',
    fhir_composition_allergies_section_text.div = append('Kein Text für diese Section vorhanden.'),

    // section medications
    fhir_composition.section as fhir_composition_medications_section,
    fhir_composition_medications_section.title = 'Medikationsliste (Medication Summary)',
    fhir_composition_medications_section.code as fhir_composition_medications_section_code,
    fhir_composition_medications_section_code.coding as fhir_composition_medications_section_code_coding,
    fhir_composition_medications_section_code_coding.system = 'http://loinc.org',
    fhir_composition_medications_section_code_coding.code = '10160-0',
    /*fhir_composition_medications_section.emptyReason as fhir_composition_medications_section_emptyReason,
    fhir_composition_medications_section_emptyReason.coding as fhir_composition_medications_section_emptyReason_coding,
    fhir_composition_medications_section_emptyReason_coding.system = 'http://terminology.hl7.org/CodeSystem/list-empty-reason',
    fhir_composition_medications_section_emptyReason_coding.code = 'unavailable',*/
    fhir_composition_medications_section.text as fhir_composition_medications_section_text,
    fhir_composition_medications_section_text.status = 'additional',
    fhir_composition_medications_section_text.div = append('Medication summary generated from CDA eMedication. Please refer to the structured entries for details on current and past medications.'),

    // section procedures
    fhir_composition.section as fhir_composition_procedures_section,
    fhir_composition_procedures_section.title = 'Eingriffe und Therapien (History of Procedures)',
    fhir_composition_procedures_section.code as fhir_composition_procedures_section_code,
    fhir_composition_procedures_section_code.coding as fhir_composition_procedures_section_code_coding,
    fhir_composition_procedures_section_code_coding.system = 'http://loinc.org',
    fhir_composition_procedures_section_code_coding.code = '47519-4',
    fhir_composition_procedures_section.emptyReason as fhir_composition_procedures_section_emptyReason,
    fhir_composition_procedures_section_emptyReason.coding as fhir_composition_procedures_section_emptyReason_coding,
    fhir_composition_procedures_section_emptyReason_coding.system = 'http://terminology.hl7.org/CodeSystem/list-empty-reason',
    fhir_composition_procedures_section_emptyReason_coding.code = 'unavailable',
    fhir_composition_procedures_section.text as fhir_composition_procedures_section_text,
    fhir_composition_procedures_section_text.status = 'empty',
    fhir_composition_procedures_section_text.div = append('Kein Text für diese Section vorhanden.'),

    // section medical devices
    fhir_composition.section as fhir_composition_devices_section,
    fhir_composition_devices_section.title = 'Implantate, medizinische Geräte (Medical Devices)',
    fhir_composition_devices_section.code as fhir_composition_devices_section_code,
    fhir_composition_devices_section_code.coding as fhir_composition_devices_section_code_coding,
    fhir_composition_devices_section_code_coding.system = 'http://loinc.org',
    fhir_composition_devices_section_code_coding.code = '46264-8',
    fhir_composition_devices_section.emptyReason as fhir_composition_devices_section_emptyReason,
    fhir_composition_devices_section_emptyReason.coding as fhir_composition_devices_section_emptyReason_coding,
    fhir_composition_devices_section_emptyReason_coding.system = 'http://terminology.hl7.org/CodeSystem/list-empty-reason',
    fhir_composition_devices_section_emptyReason_coding.code = 'unavailable',
    fhir_composition_devices_section.text as fhir_composition_devices_section_text,
    fhir_composition_devices_section_text.status = 'empty',
    fhir_composition_devices_section_text.div = append('Kein Text für diese Section vorhanden.')
    "prefillRequiredApsSections";

    // structuredBody/component/section -> Composition.section
    cda_structuredBody.component as cda_structuredBody_component then {
     cda_structuredBody_component.section as cda_section then CdaEmedSectionToFhir(cda, cda_section, fhir_composition, fhir_patient, fhir_bundle);
   } "CdaEmedBodyToFhir";
}

group CdaEmedSectionToFhir(source cda: ClinicalDocument, source cda_section: Section, target fhir_composition: Composition, target fhir_patient: Patient, target fhir_bundle: Bundle) {
   
  // Only map section if it contains Medication entries (LOINC code 10160-0)
   cda_section as cda_section where ($this.code.code = '10160-0') then {
      cda_section.entry as cda_entry then {
         cda_entry.supply as cda_entry_supply then {
          // section/entry/supply -> MedicationDispense
            cda_entry_supply where templateId.where(root = '1.2.40.0.34.11.8.2.3.1') then CdaEmedAbgabeEntryToFhir(cda, cda_entry_supply, fhir_composition, fhir_patient, fhir_bundle) "CdaEmedAbgabeEntryToFhir";
          // section/entry/supply -> MedicationRequest
            cda_entry_supply where templateId.where(root = '1.2.40.0.34.11.8.1.3.1') then CdaEmedVerordnungEntryToFhir(cda, cda_entry_supply, fhir_composition, fhir_patient, fhir_bundle) "CdaEmedVerordnungEntryToFhir";
         }
      }
   } "CdaEmedSectionToFhir";
}

group CdaEmedAbgabeEntryToFhir(source cda: ClinicalDocument, source cda_supply: Supply, target fhir_composition: Composition, target fhir_patient: Patient, target fhir_bundle: Bundle) {

  cda_supply ->
    // create MedicationDispense
    fhir_bundle.entry as fhir_bundle_entry,
    fhir_bundle_entry.resource = create('MedicationDispense') as fhir_medicationDispense,
    fhir_medicationDispense.meta as fhir_medicationDispense_meta,
    fhir_medicationDispense_meta.profile = 'https://fhir.hl7.at/elga/aps/r4/StructureDefinition/at-aps-medicationdispense',
    fhir_medicationDispense.id = uuid() as fhir_medicationDispense_id,
    fhir_bundle_entry.fullUrl = append('urn:uuid:', fhir_medicationDispense_id),
    fhir_medicationDispense.status = 'completed',
    // create MedicationRequest
    fhir_bundle.entry as fhir_bundle_entry2,
    fhir_bundle_entry2.resource = create ('MedicationRequest') as fhir_medicationRequest,
    fhir_medicationRequest.meta as fhir_medicationRequest_meta,
    fhir_medicationRequest_meta.profile = 'https://fhir.hl7.at/elga/aps/r4/StructureDefinition/at-aps-medicationrequest',
    fhir_medicationRequest.id = uuid() as fhir_medicationRequest_id,
    fhir_bundle_entry2.fullUrl = append('urn:uuid:', fhir_medicationRequest_id),
    fhir_medicationRequest.status = 'completed',
    fhir_medicationRequest.subject = create('Reference') as fhir_medicationRequest_subject_reference,
    fhir_medicationRequest.intent = 'instance-order',
    fhir_patient.id as fhir_patient_id,
    fhir_medicationRequest_subject_reference.reference = append('urn:uuid:', fhir_patient_id),
    fhir_medicationRequest_subject_reference.type = 'Patient',
    // link MedicationRequest to MedicationDispense
    fhir_medicationDispense.authorizingPrescription = create('Reference') as fhir_medicationDispense_authorizingPrescription_reference,
    fhir_medicationDispense_authorizingPrescription_reference.reference = append('urn:uuid:', fhir_medicationRequest_id),
    fhir_medicationDispense_authorizingPrescription_reference.type = 'MedicationRequest',
    // link MedicationDispense to Composition
    fhir_composition.section as fhir_composition_medications_section where (%resource.section.entry.code.coding.code = '10160-0'),
    fhir_composition_medications_section.entry as fhir_composition_medications_section_entry,
    fhir_composition_medications_section_entry.reference as fhir_composition_medications_section_entry_reference,
    fhir_composition_medications_section_entry_reference.type = 'MedicationDispense',
    fhir_composition_medications_section_entry_reference.reference = append('urn:uuid:', fhir_medicationDispense_id),
    // link MedicationRequest to Composition
    fhir_composition_medications_section.entry as fhir_composition_medications_section_entry2,
    fhir_composition_medications_section_entry2.reference as fhir_composition_medications_section_entry2_reference,
    fhir_composition_medications_section_entry2_reference.type = 'MedicationRequest',
    fhir_composition_medications_section_entry2_reference.reference = append('urn:uuid:', fhir_medicationRequest_id) then {
      cda_supply.id -> fhir_medicationDispense.identifier;
      cda_supply.code -> fhir_medicationDispense.status;
      cda_supply.quantity -> fhir_medicationDispense.quantity;

      // create Medication
      cda_supply.product as cda_product -> fhir_bundle.entry as fhir_bundle_entry3,
      fhir_bundle_entry3.resource = create('Medication') as fhir_medication,
      fhir_medication.meta as fhir_medication_meta,
      fhir_medication_meta.profile = 'https://fhir.hl7.at/elga/aps/r4/StructureDefinition/at-aps-medication',
      fhir_medication.id = uuid() as fhir_medication_id,
      fhir_bundle_entry3.fullUrl = append('urn:uuid:', fhir_medication_id)/*,
      fhir_composition.section = create('Reference') as fhir_composition_section_reference,
      fhir_composition_section_reference.reference = append('urn:uuid:', fhir_medication_id),
      fhir_composition_section_reference.type = 'Medication',*/
      // link MedicationDispense to Medication
      fhir_medicationDispense.medication = create('Reference') as fhir_medicationDispense_medication_reference,
      fhir_medicationDispense_medication_reference.reference = append('urn:uuid:', fhir_medication_id),
      fhir_medicationDispense_medication_reference.type = 'Medication',
      // link MedicationRequest to Medication
      fhir_medicationRequest.medication = create('Reference') as fhir_medicationRequest_medication_reference,
      fhir_medicationRequest_medication_reference.reference = append('urn:uuid:', fhir_medication_id),
      fhir_medicationRequest_medication_reference.type = 'Medication'
      then CdaEmedProductToFhirMedication(cda, cda_product, fhir_composition, fhir_medication, fhir_patient, fhir_bundle);

      cda_supply.author as cda_author then CdaEmedAbgabeSupplyAuthorToFhir(cda, cda_author, fhir_composition, fhir_medication, fhir_medicationDispense, fhir_medicationRequest, fhir_bundle);
      cda_supply.entryRelationship as cda_entryRelationship then CdaEmedAbgabeEntryRelationshipToFhir(cda, cda_entryRelationship, fhir_composition, fhir_medication, fhir_medicationDispense, fhir_medicationRequest, fhir_bundle);
      cda_supply.reference as cda_supply_reference then CdaEmedAbgabeSupplyReferenceToFhir(cda_supply_reference, fhir_medicationRequest);
    };   
}

group CdaEmedProductToFhirMedication(source cda: ClinicalDocument, source cda_product: Act, target fhir_composition: Composition, target fhir_medication: Medication, target fhir_patient: Patient, target fhir_bundle: Bundle) {
    
    cda_product then {

      // fill FHIR Medication resource with information from CDA product
      cda_product.manufacturedProduct as cda_product_manufacturedProduct then {
        cda_product_manufacturedProduct.manufacturedMaterial as cda_product_manufacturedMaterial -> fhir_medication.code = create('CodeableConcept') as fhir_medication_code then {

          cda_product_manufacturedMaterial.code as cda_product_manufacturedMaterial_code then {

            // PZN aus Hauptcode
            // ClinicalDocument/component/structuredBody/section/entry/supply/product/manufacturedProduct/manufacturedMaterial/code -> Medication.code.coding (PZN)
            cda_product_manufacturedMaterial_code where ($this.codeSystem = '1.2.40.0.34.4.16') -> fhir_medication_code.coding = create('Coding') as fhir_medication_code_coding then CECoding(cda_product_manufacturedMaterial_code, fhir_medication_code_coding);

            // Zulassungsnummer aus translation
            // ClinicalDocument/component/structuredBody/section/entry/supply/product/manufacturedProduct/manufacturedMaterial/code/translation -> Medication.code.coding (Zulassungsnummer)
            cda_product_manufacturedMaterial_code.translation as cda_product_manufacturedMaterial_code_translation where ($this.codeSystem = '1.2.40.0.34.4.17')  ->
              fhir_medication_code.coding = create('Coding') as fhir_medication_code_coding_translation then CECoding(cda_product_manufacturedMaterial_code_translation, fhir_medication_code_coding_translation);
          };

          // Name
          // ClinicalDocument/component/structuredBody/section/entry/supply/product/manufacturedProduct/manufacturedMaterial/name -> Medication.code.text
          cda_product_manufacturedMaterial.name -> fhir_medication_code.text;

          // ClinicalDocument/component/structuredBody/section/entry/supply/product/manufacturedProduct/manufacturedMaterial/formCode -> Medication.form
          cda_product_manufacturedMaterial.formCode -> fhir_medication.form;


          // ClinicalDocument/component/structuredBody/section/entry/supply/product/manufacturedProduct/manufacturedMaterial/asContent/containerPackagedMedicine/capacityQuantity -> Medication.amount
          cda_product_manufacturedMaterial.asContent as cda_product_manufacturedMaterial_asContent then {
            cda_product_manufacturedMaterial_asContent.containerPackagedMedicine as cda_product_manufacturedMaterial_asContent_containerPackagedMedicine then {
              cda_product_manufacturedMaterial_asContent_containerPackagedMedicine.capacityQuantity as capq -> 
                fhir_medication.amount = create('Ratio') as fhir_medication_amount then {
                  capq -> fhir_medication_amount.numerator = create('Quantity') as fhir_medication_amount_numerator then PQQuantity(capq, fhir_medication_amount_numerator);
                
                  capq -> fhir_medication_amount.denominator = create('Quantity') as fhir_medication_amount_denominator,
                  fhir_medication_amount_denominator.value = '1',
                  fhir_medication_amount_denominator.unit = 'Packung';
                };
            };
          };

          // ClinicalDocument/component/structuredBody/section/entry/supply/product/manufacturedProduct/manufacturedMaterial/ingredient -> Medication.ingredient
          cda_product_manufacturedMaterial.ingredient as cda_product_manufacturedMaterial_ingredient then {
            cda_product_manufacturedMaterial_ingredient.ingredient as cda_product_manufacturedMaterial_ingredient_ingredient -> fhir_medication.ingredient as fhir_medication_ingredient then {

              cda_product_manufacturedMaterial_ingredient_ingredient-> fhir_medication_ingredient.item = create('CodeableConcept') as fhir_medication_ingredient_item then {

                // Name
                cda_product_manufacturedMaterial_ingredient_ingredient.name -> fhir_medication_ingredient_item.text;
                cda_product_manufacturedMaterial_ingredient_ingredient.code as cda_product_manufacturedMaterial_ingredient_ingredient_code then {
                  // Hauptcode
                  cda_product_manufacturedMaterial_ingredient_ingredient_code where ($this.codeSystem = '2.16.840.1.113883.6.73') -> -> fhir_medication_ingredient_item.coding = create('Coding') as fhir_medication_ingredient_item_coding then CECoding(cda_product_manufacturedMaterial_ingredient_ingredient_code, fhir_medication_ingredient_item_coding);
                  // AGES Wirkstoff
                  cda_product_manufacturedMaterial_ingredient_ingredient_code where ($this.codeSystem = '1.2.40.0.34.5.156') -> fhir_medication_ingredient_item.coding = create('Coding') as fhir_medication_ingredient_item_coding3 then CECoding(cda_product_manufacturedMaterial_ingredient_ingredient_code, fhir_medication_ingredient_item_coding3);
                  // translation atc-deutsch-wido
                  cda_product_manufacturedMaterial_ingredient_ingredient_code.translation as cda_product_manufacturedMaterial_ingredient_ingredient_code_translation where ($this.codeSystem = '1.2.276.0.76.5.558') -> fhir_medication_ingredient_item.coding = create('Coding') as fhir_medication_ingredient_item_coding2 then CECoding(cda_product_manufacturedMaterial_ingredient_ingredient_code_translation,fhir_medication_ingredient_item_coding2);
                };
              };
            };
          };
        };      
      };
    };
}

group CdaEmedAbgabeSupplyAuthorToFhir(source cda: ClinicalDocument, source cda_author: Author, target fhir_composition: Composition, target fhir_medication: Medication, target fhir_medicationDispense: MedicationDispense, target fhir_medicationRequest: MedicationRequest, target fhir_bundle: Bundle) {
    

  // Author is Person -> map to PractitionerRole and Practitioner
  cda_author.assignedAuthor as cda_author_assignedAuthor where ($this.assignedPerson.exists()) then {

      // Time of dispensation of medication
      cda_author.time -> fhir_medicationDispense.whenHandedOver;

      // create FHIR PractitionerRole resource for the assignedAuthor
      cda_author_assignedAuthor -> fhir_bundle.entry as fhir_bundle_entry,
      fhir_bundle_entry.resource = create('PractitionerRole') as fhir_practitionerRole,
      fhir_practitionerRole.meta as fhir_practitionerRole_meta,
      fhir_practitionerRole_meta.profile = 'https://fhir.hl7.at/elga/aps/r4/StructureDefinition/at-aps-practitionerrole',
      fhir_practitionerRole.id = uuid() as fhir_practitionerRole_id,
      fhir_bundle_entry.fullUrl = append('urn:uuid:', fhir_practitionerRole_id),
      // link PractitionerRole to MedicationDispense
      fhir_medicationDispense.performer as fhir_medicationDispense_performer,
      fhir_medicationDispense_performer.actor =  = create('Reference') as fhir_medicationDispense_performer_reference,
      fhir_medicationDispense_performer_reference.reference = append('urn:uuid:', fhir_practitionerRole_id),
      fhir_medicationDispense_performer_reference.type = 'PractitionerRole',
      // create Practitioner
      fhir_bundle.entry as fhir_bundle_entry2,
      fhir_bundle_entry2.resource = create('Practitioner') as fhir_practitioner,
      fhir_practitioner.meta as fhir_practitioner_meta,
      fhir_practitioner_meta.profile = 'https://fhir.hl7.at/elga/aps/r4/StructureDefinition/at-aps-practitioner',
      fhir_practitioner.id = uuid() as fhir_practitioner_id,
      fhir_bundle_entry2.fullUrl = append('urn:uuid:', fhir_practitioner_id),
      // link Practitioner to PractitionerRole
      fhir_practitionerRole.practitioner = create('Reference') as fhir_practitionerRole_practitioner_reference,
      fhir_practitionerRole_practitioner_reference.reference = append('urn:uuid:', fhir_practitioner_id),
      fhir_practitionerRole_practitioner_reference.type = 'Practitioner' then CdaAuthorToFhirPractitionerAndPractitionerRole(cda_author, fhir_practitioner, fhir_practitionerRole, fhir_bundle) "CdaAuthorToFhirPractitionerAndPractitionerRole";
  };
      
  // Author is Device -> map to Device
  cda_author.assignedAuthor as cda_author_assignedAuthor where ($this.assignedAuthoringDevice.exists()) then {

      // create FHIR Device resource for the assignedAuthor
      cda_author_assignedAuthor -> fhir_bundle.entry as fhir_bundle_entry,
      fhir_bundle_entry.resource = create('Device') as fhir_device,
      fhir_device.meta as fhir_device_meta,
      fhir_device_meta.profile = 'https://fhir.hl7.at/elga/aps/r4/StructureDefinition/at-aps-device',
      fhir_device.id = uuid() as fhir_device_id,
      fhir_bundle_entry.fullUrl = append('urn:uuid:', fhir_device_id),
      fhir_composition.author = create('Reference') as fhir_composition_author_reference,
      fhir_composition_author_reference.reference = append('urn:uuid:', fhir_device_id),
      fhir_composition_author_reference.type = 'Device' then CdaAuthorToFhirDevice(cda_author, fhir_device, fhir_bundle) "CdaAuthorToFhirDevice";
  }; 
}

group CdaEmedAbgabeEntryRelationshipToFhir(source cda: ClinicalDocument, source cda_entryRelationship: EntryRelationship, target fhir_composition: Composition, target fhir_medication: Medication, target fhir_medicationDispense: MedicationDispense, target fhir_medicationRequest: MedicationRequest, target fhir_bundle: Bundle) {

  // Set MedicationDispense.status (mandatory element)
  /*cda -> fhir_medicationDispense.status = 'completed',
  // Create link between MedicationDispense and Medication via MedicationDispense.medication (mandatory element)
  fhir_medicationDispense.medication = create('Reference') as fhir_medicationDispense_medication_reference,
  fhir_medication.id as fhir_medication_id,
  fhir_medicationDispense_medication_reference.reference = append('urn:uuid:', fhir_medication_id),
  fhir_medicationDispense_medication_reference.type = 'Medication';*/

  // Verordnung zu Abgabe -> map to MedicationRequest
  cda_entryRelationship where ($this.typeCode = 'REFR') then {
    // section/entry/supply/entryRelationship/substanceAdministration -> MedicationRequest
    cda_entryRelationship.substanceAdministration as cda_entryRelationship_substanceAdministration then {
      cda_entryRelationship_substanceAdministration.id as cda_entryRelationship_substanceAdministration_id where ($this.root = '1.2.40.0.10.1.4.3.4.2.2') then {
        cda_entryRelationship_substanceAdministration_id -> fhir_medicationRequest.identifier = create('Identifier') as fhir_medicationRequest_identifier then II(cda_entryRelationship_substanceAdministration_id,fhir_medicationRequest_identifier);
      };
    };
  };

  cda_entryRelationship where ($this.typeCode = 'SUBJ') -> fhir_medicationDispense.dosageInstruction = create('Dosage') as fhir_medicationDispense_dosageInstruction then {
    // Zusatzinformationen für den Patienten -> MedicationDispense.dosageInstruction.patientInstruction
    // section/entry/supply/entryRelationship/act/text/@value (code PINSTRUCT) -> MedicationDispense.dosageInstruction.patientInstruction
    cda_entryRelationship.act as cda_entryRelationship_act where ($this.code.code = 'PINSTRUCT') then {

      // "Zusatzinformationen für den Patienten" -> MedicationDispense.dosageInstruction.patientInstruction
      cda_entryRelationship_act.entryRelationship as cda_entryRelationship_act_entryRelationship where ($this.act.code.code = 'ZINFO') then {
        cda_entryRelationship_act_entryRelationship.act as cda_entryRelationship_act_entryRelationship_act then {
          cda_entryRelationship_act_entryRelationship_act.text as cda_entryRelationship_act_entryRelationship_act_text then {
            cda_entryRelationship_act_entryRelationship_act_text.reference as cda_entryRelationship_act_entryRelationship_act_reference -> /*fhir_medicationDispense.dosageInstruction = create('Dosage') as fhir_medicationDispense_dosageInstruction2,*/
            fhir_medicationDispense_dosageInstruction.patientInstruction = create('string') as fhir_medicationDispense_dosageInstruction_patientInstruction then {
              cda_entryRelationship_act_entryRelationship_act_reference.value as cda_entryRelationship_act_entryRelationship_act_reference_value then {
                  
                cda.component as cda_component then {
                  cda_component.structuredBody as cda_structuredBody then {
                    cda_structuredBody.component as cda_structuredBody_component then {
                      cda_structuredBody_component.section as cda_section then {
                        cda_section.text as cda_section_text then {

                          // section/text -> Narrative.div
                          cda_section_text -> 
                          // Create Narrative (same datatype as in Composition.section.text)
                          create('Narrative') as fhir_narrative,
                          // section/text -> Narrative.div
                          fhir_narrative.div = cda_section_text as fhir_narrative_div,
                                        
                          // Create string
                          create('string') as fhir_string,
                          // Convert test_div to a FHIR string
                          fhir_string = (fhir_narrative_div),
                    
                          // Create substring from the ID (identified by cda_supply_code_reference_value) till the end of fhir_string
                          create('string') as fhir_substring_01,
                          // cda_entryRelationship_act_entryRelationship_act_reference_value.substring(1) = removing '#' from reference/@value (e.g. '#commentRef-1' becomes 'commentRef-1')
                          // fhir_string.indexOf(cda_entryRelationship_act_entryRelationship_act_reference_value.substring(1)) = the position of the ID within section/text
                          fhir_substring_01 = (fhir_string.substring(fhir_string.indexOf(cda_entryRelationship_act_entryRelationship_act_reference_value.substring(1)))),
                    
                          // Create a substring from the first occurrence of > character till the end of fhir_substring_01
                          create('string') as fhir_substring_02,
                          fhir_substring_02 = (fhir_substring_01.substring(fhir_substring_01.indexOf('>') + 1)),
                    
                          // Create a substring from the start till the first occurrence of < character
                          fhir_medicationDispense_dosageInstruction_patientInstruction = (fhir_substring_02.substring(0, fhir_substring_02.indexOf('<')));
                        }; 
                      };
                    };
                  };
                };
              };
            };
          };
        };
      };

      // "Informationen zur alternativen Einnahme" -> MedicationDispense.dosageInstruction.text
      cda_entryRelationship_act.entryRelationship as cda_entryRelationship_act_entryRelationship where ($this.act.code.code = 'ALTEIN') then {
        cda_entryRelationship_act_entryRelationship.act as cda_entryRelationship_act_entryRelationship_act then {
          cda_entryRelationship_act_entryRelationship_act.text as cda_entryRelationship_act_entryRelationship_act_text then {
            cda_entryRelationship_act_entryRelationship_act_text.reference as cda_entryRelationship_act_entryRelationship_act_reference -> /*fhir_medicationDispense.dosageInstruction = create('Dosage') as fhir_medicationDispense_dosageInstruction3,*/
            fhir_medicationDispense_dosageInstruction.text = create('string') as fhir_medicationDispense_dosageInstruction_text then {
              cda_entryRelationship_act_entryRelationship_act_reference.value as cda_entryRelationship_act_entryRelationship_act_reference_value then {
                  
                cda.component as cda_component then {
                  cda_component.structuredBody as cda_structuredBody then {
                    cda_structuredBody.component as cda_structuredBody_component then {
                      cda_structuredBody_component.section as cda_section then {
                        cda_section.text as cda_section_text then {

                          // section/text -> Narrative.div
                          cda_section_text -> 
                          // Create Narrative (same datatype as in Composition.section.text)
                          create('Narrative') as fhir_narrative,
                          // section/text -> Narrative.div
                          fhir_narrative.div = cda_section_text as fhir_narrative_div,
                                        
                          // Create string
                          create('string') as fhir_string,
                          // Convert test_div to a FHIR string
                          fhir_string = (fhir_narrative_div),
                    
                          // Create substring from the ID (identified by cda_supply_code_reference_value) till the end of fhir_string
                          create('string') as fhir_substring_01,
                          // cda_entryRelationship_act_entryRelationship_act_reference_value.substring(1) = removing '#' from reference/@value (e.g. '#commentRef-1' becomes 'commentRef-1')
                          // fhir_string.indexOf(cda_entryRelationship_act_entryRelationship_act_reference_value.substring(1)) = the position of the ID within section/text
                          fhir_substring_01 = (fhir_string.substring(fhir_string.indexOf(cda_entryRelationship_act_entryRelationship_act_reference_value.substring(1)))),
                    
                          // Create a substring from the first occurrence of > character till the end of fhir_substring_01
                          create('string') as fhir_substring_02,
                          fhir_substring_02 = (fhir_substring_01.substring(fhir_substring_01.indexOf('>') + 1)),

                          // Create a substring from the start till the first occurrence of < character
                          //create('string') as fhir_substring_03,
                          //fhir_substring_03 = (fhir_substring_02.substring(0, fhir_substring_02.indexOf('<'))),
                          //create('string') as fhir_string_05, fhir_string_05 = (iif(fhir_medicationDispense_dosageInstruction_text.empty(),'',fhir_medicationDispense_dosageInstruction_text)),
                          fhir_medicationDispense_dosageInstruction_text.div = (fhir_substring_02.substring(0, fhir_substring_02.indexOf('<')));//(fhir_string_05 + '|' + fhir_string_03);
                        };
                      };
                    };
                  };
                };
              };
            };
          };
        };
      };

      // "Informationen zur Arznei" -> Medication.text
      cda_entryRelationship_act.entryRelationship as cda_entryRelationship_act_entryRelationship where ($this.act.code.code = 'ARZNEIINFO') then {
        cda_entryRelationship_act_entryRelationship.act as cda_entryRelationship_act_entryRelationship_act then {
          cda_entryRelationship_act_entryRelationship_act.text as cda_entryRelationship_act_entryRelationship_act_text then {
            cda_entryRelationship_act_entryRelationship_act_text.reference as cda_entryRelationship_act_entryRelationship_act_reference -> fhir_medication.text = create('Narrative') as fhir_medication_text then {
              cda_entryRelationship_act_entryRelationship_act_reference.value as cda_entryRelationship_act_entryRelationship_act_reference_value then {
                  
                cda.component as cda_component then {
                  cda_component.structuredBody as cda_structuredBody then {
                    cda_structuredBody.component as cda_structuredBody_component then {
                      cda_structuredBody_component.section as cda_section then {
                        cda_section.text as cda_section_text then {

                          // section/text -> Narrative.div
                          cda_section_text -> 
                          // Create Narrative (same datatype as in Composition.section.text)
                          create('Narrative') as fhir_narrative,
                          // section/text -> Narrative.div
                          fhir_narrative.div = cda_section_text as fhir_narrative_div,
                                        
                          // Create string
                          create('string') as fhir_string,
                          // Convert test_div to a FHIR string
                          fhir_string = (fhir_narrative_div),
                    
                          // Create substring from the ID (identified by cda_supply_code_reference_value) till the end of fhir_string
                          create('string') as fhir_substring_01,
                          // cda_entryRelationship_act_entryRelationship_act_reference_value.substring(1) = removing '#' from reference/@value (e.g. '#commentRef-1' becomes 'commentRef-1')
                          // fhir_string.indexOf(cda_entryRelationship_act_entryRelationship_act_reference_value.substring(1)) = the position of the ID within section/text
                          fhir_substring_01 = (fhir_string.substring(fhir_string.indexOf(cda_entryRelationship_act_entryRelationship_act_reference_value.substring(1)))),
                    
                          // Create a substring from the first occurrence of > character till the end of fhir_substring_01
                          create('string') as fhir_substring_02,
                          fhir_substring_02 = (fhir_substring_01.substring(fhir_substring_01.indexOf('>') + 1)),

                          // Create a substring from the start till the first occurrence of < character
                          /*create('string') as fhir_string_03,
                          fhir_string_03 = (fhir_substring_02.substring(0, fhir_substring_02.indexOf('<'))),
                          create('Narrative') as fhir_medication_narrative,
                          fhir_medication.text = cast((iif(fhir_medication.text.empty(),fhir_medication_annotation,fhir_medication.text),'Annotation')),
                          create('string') as fhir_string_05, fhir_string_05 = (iif(fhir_medication_text.text.empty(),'',fhir_medication_text.text)),
                          fhir_medication_text.text = (fhir_string_05 + '|' + fhir_string_03),
                          fhir_medication.text = (fhir_substring_02.substring(0, fhir_substring_02.indexOf('<')));*/
                          fhir_medication_text.div = fhir_substring_01;//(fhir_substring_02.substring(0, fhir_substring_02.indexOf('<')));
                        };
                      };
                    };
                  };
                };
              };
            };
          };
        };
      };
    };

    // Informationen zur Abgabe -> MedicationDispense.dosageInstruction.text
    // section/entry/supply/entryRelationship/act/text/@value (code FINSTRUCT) -> MedicationDispense.dosageInstruction
    cda_entryRelationship.act as cda_entryRelationship_act where ($this.code.code = 'FINSTRUCT') then {

      // Ergänzende Informationen zur Abgabe -> MedicationDispense.dosageInstruction.text
      // section/entry/supply/entryRelationship/act/text/@value (code ERGINFO) -> MedicationDispense.dosageInstruction
      cda_entryRelationship_act.entryRelationship as cda_entryRelationship_act_entryRelationship where ($this.act.code.code = 'ERGINFO') then {
        cda_entryRelationship_act_entryRelationship.act as cda_entryRelationship_act_entryRelationship_act then {
          cda_entryRelationship_act_entryRelationship_act.text as cda_entryRelationship_act_entryRelationship_act_text then {
            cda_entryRelationship_act_entryRelationship_act_text.reference as cda_entryRelationship_act_entryRelationship_act_reference -> /*fhir_medicationDispense.dosageInstruction = create('Dosage') as fhir_medicationDispense_dosageInstruction2,*/
            fhir_medicationDispense_dosageInstruction.text = create('string') as fhir_medicationDispense_dosageInstruction_text then {
              cda_entryRelationship_act_entryRelationship_act_reference.value as cda_entryRelationship_act_entryRelationship_act_reference_value then {
                        
                cda.component as cda_component then {
                  cda_component.structuredBody as cda_structuredBody then {
                    cda_structuredBody.component as cda_structuredBody_component then {
                      cda_structuredBody_component.section as cda_section then {
                        cda_section.text as cda_section_text then {

                          // section/text -> Narrative.div
                          cda_section_text -> 
                          // Create Narrative (same datatype as in Composition.section.text)
                          create('Narrative') as fhir_narrative,
                          // section/text -> Narrative.div
                          fhir_narrative.div = cda_section_text as fhir_narrative_div,
                                              
                          // Create string
                          create('string') as fhir_string,
                          // Convert test_div to a FHIR string
                          fhir_string = (fhir_narrative_div),
                            
                          // Create substring from the ID (identified by cda_supply_code_reference_value) till the end of fhir_string
                          create('string') as fhir_substring_01,
                          // cda_entryRelationship_act_entryRelationship_act_reference_value.substring(1) = removing '#' from reference/@value (e.g. '#commentRef-1' becomes 'commentRef-1')
                          // fhir_string.indexOf(cda_entryRelationship_act_entryRelationship_act_reference_value.substring(1)) = the position of the ID within section/text
                          fhir_substring_01 = (fhir_string.substring(fhir_string.indexOf(cda_entryRelationship_act_entryRelationship_act_reference_value.substring(1)))),
                            
                          // Create a substring from the first occurrence of > character till the end of fhir_substring_01
                          create('string') as fhir_substring_02,
                          fhir_substring_02 = (fhir_substring_01.substring(fhir_substring_01.indexOf('>') + 1)),
                                  
                          // Create a substring from the start till the first occurrence of < character
                          //create('string') as fhir_string_03,
                          //fhir_string_03 = (fhir_substring_02.substring(0, fhir_substring_02.indexOf('<'))),
                          //create('string') as fhir_string_05, fhir_string_05 = (iif(fhir_medicationDispense_dosageInstruction_text.empty(),' ',fhir_medicationDispense_dosageInstruction_text)),
                          fhir_medicationDispense_dosageInstruction_text = (fhir_substring_02.substring(0, fhir_substring_02.indexOf('<'))); //(fhir_string_05 + '|' + fhir_string_03);
                        };
                      };
                    };
                  };
                };
              };
            };
          };
        };
      };

      // Magistrale Zubereitung -> Medication.text
      // section/entry/supply/entryRelationship/act/text/@value (code MAGZUB) -> Medication.text
      cda_entryRelationship_act.entryRelationship as cda_entryRelationship_act_entryRelationship where ($this.act.code.code = 'MAGZUB') then {
        cda_entryRelationship_act_entryRelationship.act as cda_entryRelationship_act_entryRelationship_act then {
          cda_entryRelationship_act_entryRelationship_act.text as cda_entryRelationship_act_entryRelationship_act_text then {
            cda_entryRelationship_act_entryRelationship_act_text.reference as cda_entryRelationship_act_entryRelationship_act_reference -> fhir_medication.text = create('Narrative') as fhir_medication_text then {
              cda_entryRelationship_act_entryRelationship_act_reference.value as cda_entryRelationship_act_entryRelationship_act_reference_value then {
                        
                cda.component as cda_component then {
                  cda_component.structuredBody as cda_structuredBody then {
                    cda_structuredBody.component as cda_structuredBody_component then {
                      cda_structuredBody_component.section as cda_section then {
                        cda_section.text as cda_section_text then {

                          // section/text -> Narrative.div
                          cda_section_text -> 
                          // Create Narrative (same datatype as in Composition.section.text)
                          create('Narrative') as fhir_narrative,
                          // section/text -> Narrative.div
                          fhir_narrative.div = cda_section_text as fhir_narrative_div,
                                              
                          // Create string
                          create('string') as fhir_string,
                          // Convert test_div to a FHIR string
                          fhir_string = (fhir_narrative_div),
                              
                          // Create substring from the ID (identified by cda_supply_code_reference_value) till the end of fhir_string
                          create('string') as fhir_substring_01,
                          // cda_entryRelationship_act_entryRelationship_act_reference_value.substring(1) = removing '#' from reference/@value (e.g. '#commentRef-1' becomes 'commentRef-1')
                          // fhir_string.indexOf(cda_entryRelationship_act_entryRelationship_act_reference_value.substring(1)) = the position of the ID within section/text
                          fhir_substring_01 = (fhir_string.substring(fhir_string.indexOf(cda_entryRelationship_act_entryRelationship_act_reference_value.substring(1)))),
                              
                          // Create a substring from the first occurrence of > character till the end of fhir_substring_01
                          create('string') as fhir_substring_02,
                          fhir_substring_02 = (fhir_substring_01.substring(fhir_substring_01.indexOf('>') + 1)),

                          // Create a substring from the start till the first occurrence of < character
                          //create('Narrative') as fhir_narrative2,
                          //fhir_narrative2.div = (fhir_substring_02.substring(0, fhir_substring_02.indexOf('<'))),
                          //create('string') as fhir_string_04,
                          //fhir_string_04 = (iif(fhir_medication.text.div.empty(),fhir_string_03,(fhir_medication.text.div))),
                          //create('string') as fhir_string_05, fhir_string_05 = (iif(fhir_medication_text.text.empty(),'',fhir_medication_text.text)),
                          //fhir_medication_text = fhir_narrative2;
                          //fhir_medication.text = (fhir_substring_02.substring(0, fhir_substring_02.indexOf('<')));

                          /*create('string') as fhir_string_03,
                          fhir_string_03 = (fhir_substring_02.substring(0, fhir_substring_02.indexOf('<'))),
                          create('Annotation') as fhir_medication_annotation,
                          fhir_medication.text = cast((iif(fhir_medication.text.empty(),fhir_medication_annotation,fhir_medication.text),'Annotation')),
                          create('string') as fhir_string_05, fhir_string_05 = (iif(fhir_medication_text.text.empty(),'',fhir_medication_text.text)),
                          fhir_medication_text.text = (fhir_string_05 + '|' + fhir_string_03),
                          fhir_medication.text = (fhir_substring_02.substring(0, fhir_substring_02.indexOf('<')));*/
                          fhir_medication_text.div = fhir_substring_01;//(fhir_substring_02.substring(0, fhir_substring_02.indexOf('<')));
                        };
                      };
                    };
                  };
                };
              };
            };
          };
        };
      };
    };
  };
  
  // Einnahmedauer, Dosierungsinformationen und Art der Anwendung (1.3.6.1.4.1.19376.1.9.1.3.6)
  cda_entryRelationship where ($this.substanceAdministration.exists()) -> fhir_medicationDispense.dosageInstruction = create('Dosage') as fhir_medicationDispense_dosageInstruction, fhir_medicationDispense_dosageInstruction.timing /*= create('Timing')*/ as fhir_medicationDispense_dosageInstruction_timing then {

    //fhir_medicationDispense_dosageInstruction_timing.event = now();
    // Aufsteigende Nummerierung der Unterelemente
    cda_entryRelationship.sequenceNumber -> fhir_medicationDispense_dosageInstruction.sequence;

    cda_entryRelationship.substanceAdministration as cda_entryRelationship_substanceAdministration then {
      
      // Normal Dosing
      // Einnahmedauer Duration: Width-Element vorhanden -> MedicationDispense.dosageInstruction.timing.boundsDuration
      cda_entryRelationship_substanceAdministration.effectiveTime: IVL_TS as cda_entryRelationship_substanceAdministration_effectiveTime ->
      fhir_medicationDispense_dosageInstruction_timing.boundsDuration = create('Duration') as fhir_medicationDispense_dosageInstruction_timing_boundsDuration then {
        // effectiveTime/width
        cda_entryRelationship_substanceAdministration_effectiveTime.width as cda_entryRelationship_substanceAdministration_effectiveTime_width then PQQuantity(cda_entryRelationship_substanceAdministration_effectiveTime_width,fhir_medicationDispense_dosageInstruction_timing_boundsDuration);
      };
      // Einnahmedauer Periode: Phase und Period-Element vorhanden -> MedicationDispense.dosageInstruction.timing.boundsPeriod
      cda_entryRelationship_substanceAdministration.effectiveTime: PIVL_TS as cda_entryRelationship_substanceAdministration_effectiveTime -> fhir_medicationDispense_dosageInstruction_timing.boundsPeriod = create('Period') as fhir_medicationDispense_dosageInstruction_timing_boundsPeriod then {
        // Zeitraum und Periodeneinheit der Dosis
        // Einnahmedauer Period -> MedicationDispense.dosageInstruction.timing.boundsPeriod
        cda_entryRelationship_substanceAdministration_effectiveTime.period as cda_entryRelationship_substanceAdministration_effectiveTime_period then PQQuantity(cda_entryRelationship_substanceAdministration_effectiveTime_period,fhir_medicationDispense_dosageInstruction_timing_boundsPeriod);
        // Erstes Datum des Wochentages nach Einnahmebeginn
        // TODO: Klären Transformation Datum zu Wochentag
        // Tagesdosierung
        cda_entryRelationship_substanceAdministration_effectiveTime.phase as cda_entryRelationship_substanceAdministration_effectiveTime_phase,
        cda_entryRelationship_substanceAdministration_effectiveTime_phase.value as cda_entryRelationship_substanceAdministration_effectiveTime_phase_value -> fhir_medicationDispense_dosageInstruction_timing.event as fhir_medicationDispense_dosageInstruction_timing_event then TSDateTime(cda_entryRelationship_substanceAdministration_effectiveTime_phase_value,fhir_medicationDispense_dosageInstruction_timing_event);
      };
      // Einnahmezeitpunkt: Event und Offset-Element vorhanden -> MedicationDispense.dosageInstruction.timing
      cda_entryRelationship_substanceAdministration.effectiveTime: EIVL_TS as cda_entryRelationship_substanceAdministration_effectiveTime then {
        // Einnahmezeitpunkt als Zeitcode
        // TODO: Abklären ob Code-Mapping erforderlich ist oder ob die Zeitpunkte direkt übernommen werden können (z.B. morgens -> AM, abends -> PM etc.) 
        cda_entryRelationship_substanceAdministration_effectiveTime.event as cda_entryRelationship_substanceAdministration_effectiveTime_event -> fhir_medicationDispense_dosageInstruction_timing.code as fhir_medicationDispense_dosageInstruction_timing_code then CECodeableConcept(cda_entryRelationship_substanceAdministration_effectiveTime_event,fhir_medicationDispense_dosageInstruction_timing_code);
        // Offset
        // TODO: Sekunden in Minuten umrechnen, da FHIR Timing.repeat.offset in Minuten angegeben wird, CDA aber in Sekunden
        cda_entryRelationship_substanceAdministration_effectiveTime.offset as cda_entryRelationship_substanceAdministration_effectiveTime_offset,
        cda_entryRelationship_substanceAdministration_effectiveTime_offset.value as cda_entryRelationship_substanceAdministration_effectiveTime_offset_value -> fhir_medicationDispense_dosageInstruction_timing.repeat as fhir_medicationDispense_dosageInstruction_timing_repeat,
        fhir_medicationDispense_dosageInstruction_timing_repeat.offset as fhir_medicationDispense_dosageInstruction_timing_repeat_offset then INT(cda_entryRelationship_substanceAdministration_effectiveTime_offset_value,fhir_medicationDispense_dosageInstruction_timing_repeat_offset);
      };
      // Komponentencontainer
      cda_entryRelationship_substanceAdministration.effectiveTime: SXPR_TS as cda_entryRelationship_substanceAdministration_effectiveTime then {
        // Tagesdosierung an MEHREREN Tagen (z.B. Montag, Mittwoch, Freitag)
        cda_entryRelationship_substanceAdministration_effectiveTime.comp: EIVL_TS as cda_entryRelationship_substanceAdministration_effectiveTime_comp then {
          // Einnahmezeitpunkt als Zeitcode
          // TODO: Abklären ob Code-Mapping erforderlich ist oder ob die Zeitpunkte direkt übernommen werden können (z.B. morgens -> AM, abends -> PM etc.) 
          cda_entryRelationship_substanceAdministration_effectiveTime_comp.event as cda_entryRelationship_substanceAdministration_effectiveTime_comp_event -> fhir_medicationDispense_dosageInstruction_timing.code as fhir_medicationDispense_dosageInstruction_timing_code then CECodeableConcept(cda_entryRelationship_substanceAdministration_effectiveTime_comp_event,fhir_medicationDispense_dosageInstruction_timing_code);
          // Offset
          cda_entryRelationship_substanceAdministration_effectiveTime_comp.offset as cda_entryRelationship_substanceAdministration_effectiveTime_comp_offset,
          cda_entryRelationship_substanceAdministration_effectiveTime_comp_offset.value as cda_entryRelationship_substanceAdministration_effectiveTime_comp_offset_value -> fhir_medicationDispense_dosageInstruction_timing.repeat as fhir_medicationDispense_dosageInstruction_timing_repeat2,
          fhir_medicationDispense_dosageInstruction_timing_repeat2.offset as fhir_medicationDispense_dosageInstruction_timing_repeat2_offset then INT(cda_entryRelationship_substanceAdministration_effectiveTime_comp_offset_value,fhir_medicationDispense_dosageInstruction_timing_repeat2_offset);
        };
        cda_entryRelationship_substanceAdministration_effectiveTime.comp: PIVL_TS as cda_entryRelationship_substanceAdministration_effectiveTime_comp then {
          // Daten der Wochentage nach Einnahmebeginn
          cda_entryRelationship_substanceAdministration_effectiveTime_comp.phase as cda_entryRelationship_substanceAdministration_effectiveTime_comp_phase,
          cda_entryRelationship_substanceAdministration_effectiveTime_comp_phase.value as cda_entryRelationship_substanceAdministration_effectiveTime_comp_phase_value -> fhir_medicationDispense_dosageInstruction_timing.event as fhir_medicationDispense_dosageInstruction_timing_event then TSDateTime(cda_entryRelationship_substanceAdministration_effectiveTime_comp_phase_value,fhir_medicationDispense_dosageInstruction_timing_event);
          // Zeitraum und Periodeneinheit der Dosis
          cda_entryRelationship_substanceAdministration_effectiveTime_comp.period as cda_entryRelationship_substanceAdministration_effectiveTime_comp_period -> fhir_medicationDispense_dosageInstruction_timing.boundsDuration = create('Duration') as fhir_medicationDispense_dosageInstruction_timing_boundsDuration then PQQuantity(cda_entryRelationship_substanceAdministration_effectiveTime_comp_period,fhir_medicationDispense_dosageInstruction_timing_boundsDuration);
        };
      };

      // Tagesdosierung
      cda_entryRelationship_substanceAdministration.doseQuantity as cda_entryRelationship_substanceAdministration_doseQuantity -> fhir_medicationDispense_dosageInstruction.doseAndRate as fhir_medicationDispense_dosageInstruction_doseAndRate,
      fhir_medicationDispense_dosageInstruction_doseAndRate.doseQuantity = create('Quantity') as fhir_medicationDispense_dosageInstruction_doseAndRate_doseQuantity then PQQuantity(cda_entryRelationship_substanceAdministration_doseQuantity,fhir_medicationDispense_dosageInstruction_doseAndRate_doseQuantity);

      // Split Dosing
      cda_entryRelationship_substanceAdministration.entryRelationship as cda_entryRelationship_substanceAdministration_entryRelationship then {

        // Aufsteigende Nummerierung der Unterelemente
        cda_entryRelationship_substanceAdministration_entryRelationship.sequenceNumber -> fhir_medicationDispense_dosageInstruction.sequence;

        cda_entryRelationship_substanceAdministration_entryRelationship.substanceAdministration as cda_entryRelationship_substanceAdministration_entryRelationship_substanceAdministration then {
          cda_entryRelationship_substanceAdministration.effectiveTime as cda_entryRelationship_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime where ($this.type = 'SXPR_TS') -> fhir_medicationDispense_dosageInstruction.timing = create('Timing') as fhir_medicationDispense_dosageInstruction_timing then {
          
            // Einnahmezeitpunkt als Zeitcode
            // TODO: Abklären ob Code-Mapping erforderlich ist oder ob die Zeitpunkte direkt übernommen werden können (z.B. morgens -> AM, abends -> PM etc.) 
            cda_entryRelationship_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime.event as cda_entryRelationship_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime_event -> fhir_medicationDispense_dosageInstruction_timing.code as fhir_medicationDispense_dosageInstruction_timing_code then CECodeableConcept(cda_entryRelationship_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime_event,fhir_medicationDispense_dosageInstruction_timing_code);
              
            // Offset
            // TODO: Sekunden in Minuten umrechnen, da FHIR Timing.repeat.offset in Minuten angegeben wird, CDA aber in Sekunden
            cda_entryRelationship_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime.offset as cda_entryRelationship_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime_offset,
            cda_entryRelationship_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime_offset.value as cda_entryRelationship_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime_offset_value -> fhir_medicationDispense_dosageInstruction_timing.repeat as fhir_medicationDispense_dosageInstruction_timing_repeat,
            fhir_medicationDispense_dosageInstruction_timing_repeat.offset as fhir_medicationDispense_dosageInstruction_timing_repeat_offset then INT(cda_entryRelationship_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime_offset_value,fhir_medicationDispense_dosageInstruction_timing_repeat_offset);

            // Komponentencontainer
            cda_entryRelationship_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime.comp: EIVL_TS as cda_entryRelationship_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime_comp then {
              // Einnahmezeitpunkt als Zeitcode
              // TODO: Abklären ob Code-Mapping erforderlich ist oder ob die Zeitpunkte direkt übernommen werden können (z.B. morgens -> AM, abends -> PM etc.) 
              cda_entryRelationship_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime_comp.event as cda_entryRelationship_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime_comp_event -> fhir_medicationDispense_dosageInstruction_timing.code as fhir_medicationDispense_dosageInstruction_timing_code then CECodeableConcept(cda_entryRelationship_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime_comp_event,fhir_medicationDispense_dosageInstruction_timing_code);
              // Offset
              cda_entryRelationship_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime_comp.offset as cda_entryRelationship_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime_comp_offset,
              cda_entryRelationship_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime_comp_offset.value as cda_entryRelationship_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime_comp_offset_value -> fhir_medicationDispense_dosageInstruction_timing.repeat as fhir_medicationDispense_dosageInstruction_timing_repeat2,
              fhir_medicationDispense_dosageInstruction_timing_repeat2.offset as fhir_medicationDispense_dosageInstruction_timing_repeat2_offset then INT(cda_entryRelationship_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime_comp_offset_value,fhir_medicationDispense_dosageInstruction_timing_repeat2_offset);
            };
            cda_entryRelationship_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime.comp: PIVL_TS as cda_entryRelationship_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime_comp then {
              // Daten der Wochentage nach Einnahmebeginn
              cda_entryRelationship_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime_comp.phase as cda_entryRelationship_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime_comp_phase,
              cda_entryRelationship_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime_comp_phase.value as cda_entryRelationship_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime_comp_phase_value -> fhir_medicationDispense_dosageInstruction_timing.event as fhir_medicationDispense_dosageInstruction_timing_event then TSDateTime(cda_entryRelationship_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime_comp_phase_value,fhir_medicationDispense_dosageInstruction_timing_event);
              // Zeitraum und Periodeneinheit der Dosis
              cda_entryRelationship_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime_comp.period as cda_entryRelationship_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime_comp_period -> fhir_medicationDispense_dosageInstruction_timing.boundsDuration = create('Duration') as fhir_medicationDispense_dosageInstruction_timing_boundsDuration then PQQuantity(cda_entryRelationship_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime_comp_period,fhir_medicationDispense_dosageInstruction_timing_boundsDuration);
            };
          };
          // Tagesdosierung
          cda_entryRelationship_substanceAdministration_entryRelationship_substanceAdministration.doseQuantity as cda_entryRelationship_substanceAdministration_doseQuantity -> fhir_medicationDispense_dosageInstruction.doseAndRate as fhir_medicationDispense_dosageInstruction_doseAndRate,
          fhir_medicationDispense_dosageInstruction_doseAndRate.doseQuantity = create('Quantity') as fhir_medicationDispense_dosageInstruction_doseAndRate_doseQuantity then PQQuantity(cda_entryRelationship_substanceAdministration_doseQuantity,fhir_medicationDispense_dosageInstruction_doseAndRate_doseQuantity);
        };
      };
    };
  };

  // Therapieart (1.2.40.0.34.11.8.1.3.4)
  cda_entryRelationship.act as cda_entryRelationship_act where ($this.templateId.root = '1.2.40.0.34.11.8.1.3.4') then {
    cda_entryRelationship_act.code as cda_entryRelationship_act_code -> fhir_medicationDispense.note = create('Annotation') as fhir_medicationDispense_usageInstruction then {
      cda_entryRelationship_act_code.code as cda_entryRelationship_code_code then {
        cda_entryRelationship_act_code.originalText as cda_entryRelationship_act_entryRelationship_act_code_originalText -> 
        create('string') as fhir_string01,
        fhir_string01 = ((cda_entryRelationship_act_entryRelationship_act_code_code) + ' | '),
        create('string') as fhir_string02, fhir_string02 = (cda_entryRelationship_act_entryRelationship_act_code), 
        fhir_medicationDispense_usageInstruction.text = (fhir_string01 + fhir_string02);
      };
    };
  };
}


group CdaEmedAbgabeSupplyReferenceToFhir(source cda_supply_reference: CDAReference, target fhir_medicationRequest: MedicationRequest) {

  // ID des VerordnungEntry-Containers (1.2.40.0.10.1.4.3.4.2.1)
  cda_supply_reference as cda_reference where ($this.typeCode = 'XCRPT') then {
    cda_reference.externalDocument as cda_reference_externalDocument then {
      cda_reference_externalDocument.id as cda_entryRelationship_reference_externalDocument_id -> fhir_medicationRequest.identifier = create('Identifier') as fhir_medicationRequest_identifier then II(cda_entryRelationship_reference_externalDocument_id,fhir_medicationRequest_identifier);
    };
  };
}


// --------------------------------------Verordnung-----------------------------------------------

group CdaEmedVerordnungEntryToFhir(source cda: ClinicalDocument, source cda_sbadm: SubstanceAdministration, target fhir_composition: Composition, target fhir_patient: Patient, target fhir_bundle: Bundle) {

  cda_sbadm ->
    // create MedicationRequest
    fhir_bundle.entry as fhir_bundle_entry,
    fhir_bundle_entry.resource = create('MedicationRequest') as fhir_medicationRequest,
    fhir_medicationRequest.meta as fhir_medicationRequest_meta,
    fhir_medicationRequest_meta.profile = 'https://fhir.hl7.at/elga/aps/r4/StructureDefinition/at-aps-medicationrequest',
    fhir_medicationRequest.id = uuid() as fhir_medicationRequest_id,
    fhir_bundle_entry.fullUrl = append('urn:uuid:', fhir_medicationRequest_id),

    // create Medication
    fhir_bundle.entry as fhir_bundle_entry2,
    fhir_bundle_entry2.resource = create('Medication') as fhir_medication,
    fhir_medication.meta as fhir_medication_meta,
    fhir_medication_meta.profile = 'https://fhir.hl7.at/elga/aps/r4/StructureDefinition/at-aps-medication',
    fhir_medication.id = uuid() as fhir_medication_id,
    fhir_bundle_entry2.fullUrl = append('urn:uuid:', fhir_medication_id),

    // link Medication to MedicationRequest
    fhir_medicationRequest.medicationReference = create('Reference') as fhir_medicationRequest_medicationReference_reference,
    fhir_medicationRequest_medicationReference_reference.reference = append('urn:uuid:', fhir_medication_id),
    fhir_medicationRequest_medicationReference_reference.type = 'Medication' then {

      // Set MedicationRequest.status (mandatory element)
      cda -> fhir_medicationRequest.status = 'completed',
      // Set MedicationRequest.subject (mandatory element)
      fhir_medicationRequest.subject = create('Reference') as fhir_medicationRequest_subject_reference,
      // Set MedicationRequest.intent (mandatory element)
      fhir_medicationRequest.intent = 'instance-order',
      fhir_patient.id as fhir_patient_id,
      fhir_medicationRequest_subject_reference.reference = append('urn:uuid:', fhir_patient_id),
      fhir_medicationRequest_subject_reference.type = 'Patient',
      // Create link between MedicationRequest and Medication via MedicationRequest.medication (mandatory element)
      fhir_medicationRequest.medication = create('Reference') as fhir_medicationRequest_medication_reference,
      fhir_medication.id as fhir_medication_id,
      fhir_medicationRequest_medication_reference.reference = append('urn:uuid:', fhir_medication_id),
      fhir_medicationRequest_medication_reference.type = 'Medication';

      // Arznei -> Medication
      cda_sbadm.consumable as cda_consumable then CdaEmedConsumableToFhirMedication(cda, cda_consumable, fhir_composition, fhir_medication, fhir_patient, fhir_bundle);

      // Verfasser der Verordnung -> Practitioner/PractitionerRole/Organization
      cda_sbadm.author as cda_author then CdaEmedVerordnungSbadmAuthorToFhir(cda, cda_author, fhir_composition, fhir_medication, fhir_medicationRequest, fhir_bundle);

      // Normal dosing
      // Einnahmedauer Periode: Phase und Period-Element vorhanden -> medicationRequest.dosageInstruction.timing.boundsPeriod
      cda_sbadm.effectiveTime: PIVL_TS as cda_substanceAdministration_effectiveTime -> fhir_medicationRequest_dosageInstruction_timing.boundsPeriod = create('Period') as fhir_medicationRequest_dosageInstruction_timing_boundsPeriod then {
        // Zeitraum und Periodeneinheit der Dosis
        // Einnahmedauer Period -> medicationRequest.dosageInstruction.timing.boundsPeriod
        cda_substanceAdministration_effectiveTime.period as cda_substanceAdministration_effectiveTime_period then PQQuantity(cda_substanceAdministration_effectiveTime_period,fhir_medicationRequest_dosageInstruction_timing_boundsPeriod);
        // Erstes Datum des Wochentages nach Einnahmebeginn
        // TODO: Klären Transformation Datum zu Wochentag
        // Tagesdosierung
        cda_substanceAdministration_effectiveTime.phase as cda_substanceAdministration_effectiveTime_phase,
        cda_substanceAdministration_effectiveTime_phase.value as cda_substanceAdministration_effectiveTime_phase_value -> fhir_medicationRequest_dosageInstruction_timing.event as fhir_medicationRequest_dosageInstruction_timing_event then TSDateTime(cda_substanceAdministration_effectiveTime_phase_value,fhir_medicationRequest_dosageInstruction_timing_event);
      };
      // Einnahmedauer Duration: Width-Element vorhanden -> medicationRequest.dosageInstruction.timing.boundsDuration
      cda_sbadm.effectiveTime: IVL_TS as cda_substanceAdministration_effectiveTime -> fhir_medicationRequest_dosageInstruction_timing.boundsDuration = create('Duration') as fhir_medicationRequest_dosageInstruction_timing_boundsDuration then {
        // effectiveTime/width
        cda_substanceAdministration_effectiveTime.width as cda_substanceAdministration_effectiveTime_width then PQQuantity(cda_substanceAdministration_effectiveTime_width,fhir_medicationRequest_dosageInstruction_timing_boundsDuration);
      };
      // Tagesdosierung
      cda_sbadm.doseQuantity as cda_substanceAdministration_doseQuantity -> fhir_medicationRequest_dosageInstruction.doseAndRate as fhir_medicationRequest_dosageInstruction_doseAndRate,
      fhir_medicationRequest_dosageInstruction_doseAndRate.doseQuantity = create('Quantity') as fhir_medicationRequest_dosageInstruction_doseAndRate_doseQuantity then PQQuantity(cda_substanceAdministration_doseQuantity,fhir_medicationRequest_dosageInstruction_doseAndRate_doseQuantity);
      
      // TODO: Check cardinality
      cda_sbadm.effectiveTime: SXPR_TS as cda_substanceAdministration_effectiveTime then {
        // Tagesdosierung an MEHREREN Tagen (z.B. Montag, Mittwoch, Freitag)
        cda_substanceAdministration_effectiveTime.comp: PIVL_TS as cda_substanceAdministration_effectiveTime_comp then {
          // Daten der Wochentage nach Einnahmebeginn
          cda_substanceAdministration_effectiveTime_comp.phase as cda_substanceAdministration_effectiveTime_comp_phase,
          cda_substanceAdministration_effectiveTime_comp_phase.value as cda_substanceAdministration_effectiveTime_comp_phase_value -> fhir_medicationRequest_dosageInstruction_timing.event as fhir_medicationRequest_dosageInstruction_timing_event then TSDateTime(cda_substanceAdministration_effectiveTime_comp_phase_value,fhir_medicationRequest_dosageInstruction_timing_event);
          // Zeitraum und Periodeneinheit der Dosis
          cda_substanceAdministration_effectiveTime_comp.period as cda_substanceAdministration_effectiveTime_comp_period -> fhir_medicationRequest_dosageInstruction_timing.boundsDuration = create('Duration') as fhir_medicationRequest_dosageInstruction_timing_boundsDuration then PQQuantity(cda_substanceAdministration_effectiveTime_comp_period,fhir_medicationRequest_dosageInstruction_timing_boundsDuration);
        };
        cda_substanceAdministration_effectiveTime.comp: EIVL_TS as cda_substanceAdministration_effectiveTime_comp then {
          // Einnahmezeitpunkt als Zeitcode
          cda_substanceAdministration_effectiveTime_comp.event as cda_substanceAdministration_effectiveTime_comp_event -> fhir_medicationRequest_dosageInstruction_timing.code as fhir_medicationRequest_dosageInstruction_timing_code then CECodeableConcept(cda_substanceAdministration_effectiveTime_comp_event,fhir_medicationRequest_dosageInstruction_timing_code);
          // Offset
          cda_substanceAdministration_effectiveTime_comp.offset as cda_substanceAdministration_effectiveTime_comp_offset,
          cda_substanceAdministration_effectiveTime_comp_offset.value as cda_substanceAdministration_effectiveTime_comp_offset_value -> fhir_medicationRequest_dosageInstruction_timing.repeat as fhir_medicationRequest_dosageInstruction_timing_repeat2,
          fhir_medicationRequest_dosageInstruction_timing_repeat2.offset as fhir_medicationRequest_dosageInstruction_timing_repeat2_offset then INT(cda_substanceAdministration_effectiveTime_comp_offset_value,fhir_medicationRequest_dosageInstruction_timing_repeat2_offset);
        };
      };

      // Split Dosing
      cda_sbadm.entryRelationship as cda_substanceAdministration_entryRelationship then {

        // Aufsteigende Nummerierung der Unterelemente
        cda_substanceAdministration_entryRelationship.sequenceNumber -> fhir_medicationRequest_dosageInstruction.sequence;

        cda_substanceAdministration_entryRelationship.substanceAdministration as cda_substanceAdministration_entryRelationship_substanceAdministration then {

          cda_substanceAdministration_entryRelationship_substanceAdministration.effectiveTime: EIVL_TS as cda_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime -> fhir_medicationRequest_dosageInstruction.timing = create('Timing') as fhir_medicationRequest_dosageInstruction_timing then {

            // Einnahmezeitpunkt als Zeitcode
            // TODO: Abklären ob Code-Mapping erforderlich ist oder ob die Zeitpunkte direkt übernommen werden können (z.B. morgens -> AM, abends -> PM etc.) 
            cda_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime.event as cda_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime_event -> fhir_medicationRequest_dosageInstruction_timing.code as fhir_medicationRequest_dosageInstruction_timing_code then CECodeableConcept(cda_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime_event,fhir_medicationRequest_dosageInstruction_timing_code);
              
            // Offset
            // TODO: Sekunden in Minuten umrechnen, da FHIR Timing.repeat.offset in Minuten angegeben wird, CDA aber in Sekunden
            cda_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime.offset as cda_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime_offset,
            cda_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime_offset.value as cda_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime_offset_value -> fhir_medicationRequest_dosageInstruction_timing.repeat as fhir_medicationRequest_dosageInstruction_timing_repeat,
            fhir_medicationRequest_dosageInstruction_timing_repeat.offset as fhir_medicationRequest_dosageInstruction_timing_repeat_offset then INT(cda_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime_offset_value,fhir_medicationRequest_dosageInstruction_timing_repeat_offset);
          };

          cda_substanceAdministration_entryRelationship_substanceAdministration.effectiveTime: SXPR_TS as cda_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime then {
            // Tagesdosierung an MEHREREN Tagen (z.B. Montag, Mittwoch, Freitag)
            cda_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime.comp: EIVL_TS as cda_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime_comp then {
              // Einnahmezeitpunkt als Zeitcode
              cda_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime_comp.event as cda_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime_comp_event -> fhir_medicationRequest_dosageInstruction_timing.code as fhir_medicationRequest_dosageInstruction_timing_code then CECodeableConcept(cda_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime_comp_event,fhir_medicationRequest_dosageInstruction_timing_code);
            };
            cda_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime: PIVL_TS as cda_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime then {
              // Daten der Wochentage nach Einnahmebeginn
              cda_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime.phase as cda_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime_phase,
              cda_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime_phase.value as cda_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime_phase_value -> fhir_medicationRequest_dosageInstruction_timing.event as fhir_medicationRequest_dosageInstruction_timing_event then TSDateTime(cda_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime_phase_value,fhir_medicationRequest_dosageInstruction_timing_event);
              // Zeitraum und Periodeneinheit der Dosis
              cda_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime.period as cda_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime_period -> fhir_medicationRequest_dosageInstruction_timing.boundsDuration = create('Duration') as fhir_medicationRequest_dosageInstruction_timing_boundsDuration then PQQuantity(cda_substanceAdministration_entryRelationship_substanceAdministration_effectiveTime_period,fhir_medicationRequest_dosageInstruction_timing_boundsDuration);
            };
          };
        };
        // Tagesdosierung
        cda_substanceAdministration_entryRelationship.doseQuantity as cda_substanceAdministration_doseQuantity -> fhir_medicationRequest_dosageInstruction.doseAndRate as fhir_medicationRequest_dosageInstruction_doseAndRate,
        fhir_medicationRequest_dosageInstruction_doseAndRate.doseQuantity = create('Quantity') as fhir_medicationRequest_dosageInstruction_doseAndRate_doseQuantity then PQQuantity(cda_substanceAdministration_doseQuantity,fhir_medicationRequest_dosageInstruction_doseAndRate_doseQuantity);
      };

      // Maximale Anzahl der Einlösungen -> medicationRequest.dispenseRequest.numberOfRepeatsAllowed
      cda_sbadm.repeatNumber as cda_substanceAdministration_repeatNumber -> fhir_medicationRequest.dispenseRequest = create('BackboneElement') as fhir_medicationRequest_dispenseRequest then {
        cda_substanceAdministration_repeatNumber -> fhir_medicationRequest.dispenseRequest.numberOfRepeatsAllowed;
      };

      // Art der Anwendung der Arznei
      cda_sbadm.routeCode as cda_substanceAdministration_routeCode -> fhir_medicationRequest_dosageInstruction.route as fhir_medicationRequest_dosageInstruction_route then CECodeableConcept(cda_substanceAdministration_routeCode,fhir_medicationRequest_dosageInstruction_route);

      // Anzahl der Packungen
      // Check cardinality
      cda_sbadm.entryRelationship as cda_substanceAdministration_entryRelationship then {
        cda_substanceAdministration_entryRelationship.supply as cda_substanceAdministration_entryRelationship_supply then {
          cda_substanceAdministration_entryRelationship_supply.quantity as cda_substanceAdministration_entryRelationship_supply_quantity ->
          fhir_medicationRequest.dispenseRequest = create('BackboneElement') as fhir_medicationRequest_dispenseRequest,
          fhir_medicationRequest_dispenseRequest.quantity = create('Quantity') as fhir_medicationRequest_dispenseRequest_quantity then PQQuantity(cda_substanceAdministration_entryRelationship_supply_quantity,fhir_medicationRequest_dispenseRequest_quantity);
        };
      };

      // Zusatzinformationen für den Patienten

      // Ergänzende Informationen zur Abgabe und magistralen Zubereitungen
      cda_sbadm.entryRelationship as cda_entryRelationship then {
        cda_entryRelationship.act as cda_entryRelationship_act where ($this.code.code = 'FINSTRUCT') then {

          // Ergänzende Informationen zur Abgabe -> MedicationDispense.dosageInstruction.text
          // section/entry/supply/entryRelationship/act/text/@value (code ERGINFO) -> MedicationDispense.dosageInstruction
          cda_entryRelationship_act.entryRelationship as cda_entryRelationship_act_entryRelationship where ($this.act.code.code = 'ERGINFO') then {
            cda_entryRelationship_act_entryRelationship.act as cda_entryRelationship_act_entryRelationship_act then {
              cda_entryRelationship_act_entryRelationship_act.text as cda_entryRelationship_act_entryRelationship_act_text then {
                cda_entryRelationship_act_entryRelationship_act_text.reference as cda_entryRelationship_act_entryRelationship_act_reference -> /*fhir_medicationDispense.dosageInstruction = create('Dosage') as fhir_medicationDispense_dosageInstruction2,*/
                  fhir_medicationDispense_dosageInstruction.text = create('string') as fhir_medicationDispense_dosageInstruction_text then {
                    cda_entryRelationship_act_entryRelationship_act_reference.value as cda_entryRelationship_act_entryRelationship_act_reference_value then {
                              
                      cda.component as cda_component then {
                        cda_component.structuredBody as cda_structuredBody then {
                          cda_structuredBody.component as cda_structuredBody_component then {
                            cda_structuredBody_component.section as cda_section then {
                              cda_section.text as cda_section_text then {
 
                                // section/text -> Narrative.div
                                cda_section_text -> 
                                // Create Narrative (same datatype as in Composition.section.text)
                                create('Narrative') as fhir_narrative,
                                // section/text -> Narrative.div
                                fhir_narrative.div = cda_section_text as fhir_narrative_div,
                                                        
                                // Create string
                                create('string') as fhir_string,
                                // Convert test_div to a FHIR string
                                fhir_string = (fhir_narrative_div),
                                  
                                // Create substring from the ID (identified by cda_supply_code_reference_value) till the end of fhir_string
                                create('string') as fhir_substring_01,
                                // cda_entryRelationship_act_entryRelationship_act_reference_value.substring(1) = removing '#' from reference/@value (e.g. '#commentRef-1' becomes 'commentRef-1')
                                // fhir_string.indexOf(cda_entryRelationship_act_entryRelationship_act_reference_value.substring(1)) = the position of the ID within section/text
                                fhir_substring_01 = (fhir_string.substring(fhir_string.indexOf(cda_entryRelationship_act_entryRelationship_act_reference_value.substring(1)))),
                                      
                                // Create a substring from the first occurrence of > character till the end of fhir_substring_01
                                create('string') as fhir_substring_02,
                                fhir_substring_02 = (fhir_substring_01.substring(fhir_substring_01.indexOf('>') + 1)),
                                        
                                // Create a substring from the start till the first occurrence of < character
                                //create('string') as fhir_string_03,
                                //fhir_string_03 = (fhir_substring_02.substring(0, fhir_substring_02.indexOf('<'))),
                                //create('string') as fhir_string_05, fhir_string_05 = (iif(fhir_medicationDispense_dosageInstruction_text.empty(),' ',fhir_medicationDispense_dosageInstruction_text)),
                                //fhir_medicationDispense_dosageInstruction_text.div = (fhir_string_05 + '|' + fhir_string_03);
                                fhir_medicationDispense_dosageInstruction_text = (fhir_substring_02.substring(0, fhir_substring_02.indexOf('<')));
                              };
                            };
                          };
                        };
                      };
                    };
                  };
                };
              };
            };
          };

          // Magistrale Zubereitung -> Medication.text
          // section/entry/supply/entryRelationship/act/text/@value (code MAGZUB) -> Medication.text
          cda_entryRelationship_act.entryRelationship as cda_entryRelationship_act_entryRelationship where ($this.act.code.code = 'MAGZUB') then {
            cda_entryRelationship_act_entryRelationship.act as cda_entryRelationship_act_entryRelationship_act then {
              cda_entryRelationship_act_entryRelationship_act.text as cda_entryRelationship_act_entryRelationship_act_text then {
                cda_entryRelationship_act_entryRelationship_act_text.reference as cda_entryRelationship_act_entryRelationship_act_reference -> fhir_medication.text as fhir_medication_text then {
                  cda_entryRelationship_act_entryRelationship_act_reference.value as cda_entryRelationship_act_entryRelationship_act_reference_value then {
                            
                    cda.component as cda_component then {
                      cda_component.structuredBody as cda_structuredBody then {
                        cda_structuredBody.component as cda_structuredBody_component then {
                          cda_structuredBody_component.section as cda_section then {
                            cda_section.text as cda_section_text then {

                              // section/text -> Narrative.div
                              cda_section_text -> 
                              // Create Narrative (same datatype as in Composition.section.text)
                              create('Narrative') as fhir_narrative,
                              // section/text -> Narrative.div
                              fhir_narrative.div = cda_section_text as fhir_narrative_div,
                                                  
                              // Create string
                              create('string') as fhir_string,
                              // Convert test_div to a FHIR string
                              fhir_string = (fhir_narrative_div),
                                  
                              // Create substring from the ID (identified by cda_supply_code_reference_value) till the end of fhir_string
                              create('string') as fhir_substring_01,
                              // cda_entryRelationship_act_entryRelationship_act_reference_value.substring(1) = removing '#' from reference/@value (e.g. '#commentRef-1' becomes 'commentRef-1')
                              // fhir_string.indexOf(cda_entryRelationship_act_entryRelationship_act_reference_value.substring(1)) = the position of the ID within section/text
                              fhir_substring_01 = (fhir_string.substring(fhir_string.indexOf(cda_entryRelationship_act_entryRelationship_act_reference_value.substring(1)))),
                                  
                              // Create a substring from the first occurrence of > character till the end of fhir_substring_01
                              create('string') as fhir_substring_02,
                              fhir_substring_02 = (fhir_substring_01.substring(fhir_substring_01.indexOf('>') + 1)),

                              // Create a substring from the start till the first occurrence of < character
                              //create('Narrative') as fhir_narrative2,
                              //fhir_narrative2.div = (fhir_substring_02.substring(0, fhir_substring_02.indexOf('<'))),
                              //create('string') as fhir_string_04,
                              //fhir_string_04 = (iif(fhir_medication.text.div.empty(),fhir_string_03,(fhir_medication.text.div))),
                              //create('string') as fhir_string_05, fhir_string_05 = (iif(fhir_medication_text.text.empty(),'',fhir_medication_text.text)),
                              fhir_medication_text.div = fhir_substring_01;//(fhir_substring_02.substring(0, fhir_substring_02.indexOf('<')));
                            };
                          };
                        };
                      };
                    };
                  };
                };
              };
            };
          };
        };
      };

      // Therapieart (1.2.40.0.34.11.8.1.3.4)
      cda_sbadm.entryRelationship as cda_substanceAdministration_entryRelationship then {
        cda_substanceAdministration_entryRelationship.act as cda_substanceAdministration_entryRelationship_act where ($this.templateId.root = '1.2.40.0.34.11.8.1.3.4') then {
          cda_substanceAdministration_entryRelationship_act.code as cda_substanceAdministration_entryRelationship_act_code -> fhir_medicationRequest.note = create('Annotation') as fhir_medicationRequest_usageInstruction then {
            cda_substanceAdministration_entryRelationship_act_code.code as cda_substanceAdministration_entryRelationship_code_code then {
              cda_substanceAdministration_entryRelationship_act_code.originalText as cda_substanceAdministration_entryRelationship_act_entryRelationship_act_code_originalText -> 
              create('string') as fhir_string01,
              fhir_string01 = ((cda_substanceAdministration_entryRelationship_act_entryRelationship_act_code_code) + ' | '),
              create('string') as fhir_string02, fhir_string02 = (cda_substanceAdministration_entryRelationship_act_entryRelationship_act_code), 
              fhir_medicationRequest_usageInstruction.text = (fhir_string01 + fhir_string02);
            };
          };
        };
      };

      // ID des Verordnungs-Entry
      cda_sbadm.reference as cda_substanceAdministration_reference where ($this.typeCode = 'XCRPT') then {
        cda_substanceAdministration_reference.externalDocument as cda_substanceAdministration_reference_externalDocument then {
          cda_substanceAdministration_reference_externalDocument.id as cda_substanceAdministration_reference_externalDocument_id -> fhir_medicationRequest.identifier = create('Identifier') as fhir_medicationRequest_identifier then II(cda_substanceAdministration_reference_externalDocument_id,fhir_medicationRequest_identifier);
        };
      };
    };
}

group CdaEmedConsumableToFhirMedication(source cda: ClinicalDocument, source cda_consumable: Consumable, target fhir_composition: Composition, target fhir_medication: Medication, target fhir_patient: Patient, target fhir_bundle: Bundle) {
    
    cda_consumable then {

      // fill FHIR Medication resource with information from CDA consumable of Verordnung-Entry
      cda_consumable.manufacturedProduct as cda_manufacturedProduct then {
        cda_manufacturedProduct.manufacturedMaterial as cda_manufacturedMaterial -> fhir_medication.code = create('CodeableConcept') as fhir_medication_code then {

          cda_manufacturedMaterial.code as cda_manufacturedMaterial_code then {

            // PZN aus Hauptcode
            // ClinicalDocument/component/structuredBody/section/entry/substanceAdministration/consumable/manufacturedProduct/manufacturedMaterial/code
            // -> Medication.code.coding (PZN)
            cda_manufacturedMaterial_code where ($this.codeSystem = '1.2.40.0.34.4.16') ->
              fhir_medication_code.coding = create('Coding') as fhir_medication_code_coding then
                CECoding(cda_manufacturedMaterial_code, fhir_medication_code_coding);

            // Zulassungsnummer aus translation
            // ClinicalDocument/component/structuredBody/section/entry/substanceAdministration/consumable/manufacturedProduct/manufacturedMaterial/code/translation
            // -> Medication.code.coding (Zulassungsnummer)
            cda_manufacturedMaterial_code.translation as cda_manufacturedMaterial_code_translation where ($this.codeSystem = '1.2.40.0.34.4.17') ->
              fhir_medication_code.coding = create('Coding') as fhir_medication_code_coding_translation then
                CECoding(cda_manufacturedMaterial_code_translation, fhir_medication_code_coding_translation);
          };

          // Name
          // ClinicalDocument/component/structuredBody/section/entry/substanceAdministration/consumable/manufacturedProduct/manufacturedMaterial/name
          // -> Medication.code.text
          cda_manufacturedMaterial.name -> fhir_medication_code.text;

          // Darreichungsform
          // ClinicalDocument/component/structuredBody/section/entry/substanceAdministration/consumable/manufacturedProduct/manufacturedMaterial/formCode
          // -> Medication.form
          cda_manufacturedMaterial.formCode -> fhir_medication.form;

          // Packungsgröße
          // ClinicalDocument/component/structuredBody/section/entry/substanceAdministration/consumable/manufacturedProduct/manufacturedMaterial/asContent/containerPackagedMedicine/capacityQuantity
          // -> Medication.amount
          cda_manufacturedMaterial.asContent as cda_asContent then {
            cda_asContent.containerPackagedMedicine as cda_containerPackagedMedicine then {
              cda_containerPackagedMedicine.capacityQuantity as capq ->
                fhir_medication.amount = create('Ratio') as fhir_medication_amount then {
                  capq -> fhir_medication_amount.numerator = create('Quantity') as fhir_medication_amount_numerator then
                    PQQuantity(capq, fhir_medication_amount_numerator);

                  capq -> fhir_medication_amount.denominator = create('Quantity') as fhir_medication_amount_denominator,
                  fhir_medication_amount_denominator.value = '1',
                  fhir_medication_amount_denominator.unit = 'Packung';
                };
            };
          };

          // Wirkstoffe
          // ClinicalDocument/component/structuredBody/section/entry/substanceAdministration/consumable/manufacturedProduct/manufacturedMaterial/ingredient
          // -> Medication.ingredient
          cda_manufacturedMaterial.ingredient as cda_ingredient then {
            cda_ingredient.ingredient as cda_ingredient_inner ->
              fhir_medication.ingredient as fhir_medication_ingredient then {

                cda_ingredient_inner ->
                  fhir_medication_ingredient.item = create('CodeableConcept') as fhir_medication_ingredient_item then {

                    // Name
                    cda_ingredient_inner.name -> fhir_medication_ingredient_item.text;

                    cda_ingredient_inner.code as cda_ingredient_inner_code then {
                      // ATC / Hauptcode
                      cda_ingredient_inner_code where ($this.codeSystem = '2.16.840.1.113883.6.73') ->
                        fhir_medication_ingredient_item.coding = create('Coding') as fhir_medication_ingredient_item_coding then
                          CECoding(cda_ingredient_inner_code, fhir_medication_ingredient_item_coding);

                      // AGES Wirkstoff
                      cda_ingredient_inner_code where ($this.codeSystem = '1.2.40.0.34.5.156') ->
                        fhir_medication_ingredient_item.coding = create('Coding') as fhir_medication_ingredient_item_coding2 then
                          CECoding(cda_ingredient_inner_code, fhir_medication_ingredient_item_coding2);

                      // translation, z.B. atc-deutsch-wido
                      cda_ingredient_inner_code.translation as cda_ingredient_inner_code_translation where ($this.codeSystem = '1.2.276.0.76.5.558') ->
                        fhir_medication_ingredient_item.coding = create('Coding') as fhir_medication_ingredient_item_coding3 then
                          CECoding(cda_ingredient_inner_code_translation, fhir_medication_ingredient_item_coding3);
                    };
                };
            };
          };
        };
      };
    };
}

group CdaEmedVerordnungSbadmAuthorToFhir(source cda: ClinicalDocument, source cda_author: Author, target fhir_composition: Composition, target fhir_medication: Medication, target fhir_medicationRequest: MedicationRequest, target fhir_bundle: Bundle) {

  // Author is Person -> map to PractitionerRole and Practitioner
  cda_author.assignedAuthor as cda_author_assignedAuthor where ($this.assignedPerson.exists()) then {

      // Date of prescription
      cda_author.time -> fhir_medicationRequest.authoredOn;

      // create FHIR PractitionerRole resource for the assignedAuthor
      cda_author_assignedAuthor -> fhir_bundle.entry as fhir_bundle_entry,
      fhir_bundle_entry.resource = create('PractitionerRole') as fhir_practitionerRole,
      fhir_practitionerRole.meta as fhir_practitionerRole_meta,
      fhir_practitionerRole_meta.profile = 'https://fhir.hl7.at/elga/aps/r4/StructureDefinition/at-aps-practitionerrole',
      fhir_practitionerRole.id = uuid() as fhir_practitionerRole_id,
      fhir_bundle_entry.fullUrl = append('urn:uuid:', fhir_practitionerRole_id),

      // link PractitionerRole to MedicationRequest as requester
      fhir_medicationRequest.requester = create('Reference') as fhir_medicationRequest_requester_reference,
      fhir_medicationRequest_requester_reference.reference = append('urn:uuid:', fhir_practitionerRole_id),
      fhir_medicationRequest_requester_reference.type = 'PractitionerRole',

      // create Practitioner
      fhir_bundle.entry as fhir_bundle_entry2,
      fhir_bundle_entry2.resource = create('Practitioner') as fhir_practitioner,
      fhir_practitioner.meta as fhir_practitioner_meta,
      fhir_practitioner_meta.profile = 'https://fhir.hl7.at/elga/aps/r4/StructureDefinition/at-aps-practitioner',
      fhir_practitioner.id = uuid() as fhir_practitioner_id,
      fhir_bundle_entry2.fullUrl = append('urn:uuid:', fhir_practitioner_id),

      // link Practitioner to PractitionerRole
      fhir_practitionerRole.practitioner = create('Reference') as fhir_practitionerRole_practitioner_reference,
      fhir_practitionerRole_practitioner_reference.reference = append('urn:uuid:', fhir_practitioner_id),
      fhir_practitionerRole_practitioner_reference.type = 'Practitioner' then
        CdaAuthorToFhirPractitionerAndPractitionerRole(cda_author, fhir_practitioner, fhir_practitionerRole, fhir_bundle) "CdaAuthorToFhirPractitionerAndPractitionerRole";
  };

  // Author is Device -> map to Device
  cda_author.assignedAuthor as cda_author_assignedAuthor where ($this.assignedAuthoringDevice.exists()) then {

      // Date of prescription
      cda_author.time -> fhir_medicationRequest.authoredOn;

      // create FHIR Device resource for the assignedAuthor
      cda_author_assignedAuthor -> fhir_bundle.entry as fhir_bundle_entry,
      fhir_bundle_entry.resource = create('Device') as fhir_device,
      fhir_device.meta as fhir_device_meta,
      fhir_device_meta.profile = 'https://fhir.hl7.at/elga/aps/r4/StructureDefinition/at-aps-device',
      fhir_device.id = uuid() as fhir_device_id,
      fhir_bundle_entry.fullUrl = append('urn:uuid:', fhir_device_id),

      // link Device to MedicationRequest as requester
      fhir_medicationRequest.requester = create('Reference') as fhir_medicationRequest_requester_reference,
      fhir_medicationRequest_requester_reference.reference = append('urn:uuid:', fhir_device_id),
      fhir_medicationRequest_requester_reference.type = 'Device' then
        CdaAuthorToFhirDevice(cda_author, fhir_device, fhir_bundle) "CdaAuthorToFhirDevice";
  };
}

