/*group CdaEmedVerordnungEntryRelationshipToFhir(source cda: ClinicalDocument, source cda_entryRelationship: EntryRelationship, target fhir_composition: Composition, target fhir_medication: Medication, target fhir_medicationRequest: MedicationRequest, target fhir_bundle: Bundle) {

  // Verordnete Menge -> MedicationRequest.dispenseRequest.quantity
  cda_entryRelationship where ($this.typeCode = 'COMP') then {
    cda_entryRelationship.supply as cda_entryRelationship_supply then {
      cda_entryRelationship_supply.quantity as cda_entryRelationship_supply_quantity ->
        fhir_medicationRequest.dispenseRequest = create('BackboneElement') as fhir_medicationRequest_dispenseRequest,
        fhir_medicationRequest_dispenseRequest.quantity = create('Quantity') as fhir_medicationRequest_dispenseRequest_quantity then
          PQQuantity(cda_entryRelationship_supply_quantity, fhir_medicationRequest_dispenseRequest_quantity);
    };
  };


  cda_entryRelationship where ($this.typeCode = 'SUBJ') -> fhir_medicationRequest.dosageInstruction = create('Dosage') as fhir_medicationRequest_dosageInstruction then {
    // Zusatzinformationen für den Patienten -> medicationRequest.dosageInstruction.patientInstruction
    // section/entry/supply/entryRelationship/act/text/@value (code PINSTRUCT) -> medicationRequest.dosageInstruction.patientInstruction
    cda_entryRelationship.act as cda_entryRelationship_act where ($this.code.code = 'PINSTRUCT') then {

  
  // Einnahmedauer, Dosierungsinformationen und Art der Anwendung (1.3.6.1.4.1.19376.1.9.1.3.6)
  cda_entryRelationship where ($this.substanceAdministration.exists()) -> fhir_medicationRequest.dosageInstruction = create('Dosage') as fhir_medicationRequest_dosageInstruction, fhir_medicationRequest_dosageInstruction.timing = create('Timing') as fhir_medicationRequest_dosageInstruction_timing then {

    //fhir_medicationRequest_dosageInstruction_timing.event = now();
    // Aufsteigende Nummerierung der Unterelemente
    cda_entryRelationship.sequenceNumber -> fhir_medicationRequest_dosageInstruction.sequence;

    cda_entryRelationship.substanceAdministration as cda_entryRelationship_substanceAdministration then {
      
      // Normal Dosing
      // Einnahmedauer Duration: Width-Element vorhanden -> medicationRequest.dosageInstruction.timing.boundsDuration
      cda_entryRelationship_substanceAdministration.effectiveTime: IVL_TS as cda_entryRelationship_substanceAdministration_effectiveTime ->
      fhir_medicationRequest_dosageInstruction_timing.boundsDuration = create('Duration') as fhir_medicationRequest_dosageInstruction_timing_boundsDuration then {
        // effectiveTime/width
        cda_entryRelationship_substanceAdministration_effectiveTime.width as cda_entryRelationship_substanceAdministration_effectiveTime_width then PQQuantity(cda_entryRelationship_substanceAdministration_effectiveTime_width,fhir_medicationRequest_dosageInstruction_timing_boundsDuration);
      };
      // Einnahmedauer Periode: Phase und Period-Element vorhanden -> medicationRequest.dosageInstruction.timing.boundsPeriod
      cda_entryRelationship_substanceAdministration.effectiveTime: PIVL_TS as cda_entryRelationship_substanceAdministration_effectiveTime -> fhir_medicationRequest_dosageInstruction_timing.boundsPeriod = create('Period') as fhir_medicationRequest_dosageInstruction_timing_boundsPeriod then {
        // Zeitraum und Periodeneinheit der Dosis
        // Einnahmedauer Period -> medicationRequest.dosageInstruction.timing.boundsPeriod
        cda_entryRelationship_substanceAdministration_effectiveTime.period as cda_entryRelationship_substanceAdministration_effectiveTime_period then PQQuantity(cda_entryRelationship_substanceAdministration_effectiveTime_period,fhir_medicationRequest_dosageInstruction_timing_boundsPeriod);
        // Erstes Datum des Wochentages nach Einnahmebeginn
        // TODO: Klären Transformation Datum zu Wochentag
        // Tagesdosierung
        cda_entryRelationship_substanceAdministration_effectiveTime.phase as cda_entryRelationship_substanceAdministration_effectiveTime_phase,
        cda_entryRelationship_substanceAdministration_effectiveTime_phase.value as cda_entryRelationship_substanceAdministration_effectiveTime_phase_value -> fhir_medicationRequest_dosageInstruction_timing.event as fhir_medicationRequest_dosageInstruction_timing_event then TSDateTime(cda_entryRelationship_substanceAdministration_effectiveTime_phase_value,fhir_medicationRequest_dosageInstruction_timing_event);
      };
      // Einnahmezeitpunkt: Event und Offset-Element vorhanden -> medicationRequest.dosageInstruction.timing
      cda_entryRelationship_substanceAdministration.effectiveTime: EIVL_TS as cda_entryRelationship_substanceAdministration_effectiveTime then {
